def parser(log: str) -> dict[str, str]:
    import json
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}

    def status_from_state(state: str, failure_present: bool = False) -> str:
        state = (state or "").lower()
        if not state and failure_present:
            return "fail"
        if state in ("passed", "pass", "success"):
            return "pass"
        if state in ("skipped", "pending", "skip"):
            return "skip"
        if state in ("failed", "fail", "panicked", "timedout", "aborted", "error"):
            return "fail"
        if failure_present:
            return "fail"
        return "fail" if state else "pass"

    def add_result(name: str, status: str, location: str | None = None) -> None:
        base = name.strip() if name else "unknown"
        candidate = base
        if candidate in results:
            if location:
                candidate = f"{base} ({location})"
            if candidate in results:
                idx = 2
                while f"{candidate} #{idx}" in results:
                    idx += 1
                candidate = f"{candidate} #{idx}"
        results[candidate] = status

    def parse_suite(suite: dict) -> None:
        suite_desc = suite.get("SuiteDescription") or suite.get("SuitePath") or "Ginkgo Suite"
        spec_reports = suite.get("SpecReports") or []
        if not spec_reports:
            if suite.get("SuiteSucceeded") is False:
                add_result(suite_desc, "fail")
            return
        for spec in spec_reports:
            parts = [suite_desc] if suite_desc else []
            for text in spec.get("ContainerHierarchyTexts") or []:
                if text:
                    parts.append(text)
            leaf = spec.get("LeafNodeText") or spec.get("LeafNodeType") or ""
            if leaf:
                parts.append(leaf)
            name = " :: ".join([p for p in parts if p])
            location = None
            loc = spec.get("LeafNodeLocation") or {}
            if isinstance(loc, dict):
                file_name = loc.get("FileName")
                line = loc.get("LineNumber")
                if file_name and line is not None:
                    location = f"{file_name}:{line}"
            if not name:
                name = location or "Ginkgo Spec"
            status = status_from_state(spec.get("State"), failure_present=bool(spec.get("Failure")))
            add_result(name, status, location=location)

    def handle_data(data) -> None:
        if isinstance(data, list):
            for item in data:
                handle_data(item)
        elif isinstance(data, dict):
            if "SpecReports" in data or "SuiteDescription" in data or "SuitePath" in data:
                parse_suite(data)

    def parse_json_stream(text: str):
        decoder = json.JSONDecoder()
        idx = 0
        objs = []
        length = len(text)
        while idx < length:
            match = re.search(r'[\{\[]', text[idx:])
            if not match:
                break
            idx += match.start()
            try:
                obj, end = decoder.raw_decode(text[idx:])
            except json.JSONDecodeError:
                idx += 1
                continue
            objs.append(obj)
            idx += end
        return objs

    data = None
    try:
        stripped = log.strip()
        if stripped:
            data = json.loads(stripped)
    except Exception:
        data = None

    if data is None:
        objs = parse_json_stream(log)
        if len(objs) == 1:
            data = objs[0]
        elif len(objs) > 1:
            data = objs

    if data is None:
        try:
            with open("/testbed/reports/ginkgo.json", "r", encoding="utf-8") as handle:
                data = json.load(handle)
        except Exception:
            data = None

    if data is not None:
        handle_data(data)

    # Fallbacks if still empty
    if not results:
        # JUnit XML parsing
        if "<testsuite" in log or "<testsuites" in log:
            suites_xml = []
            try:
                root = ET.fromstring(log)
                suites_xml = [root]
            except Exception:
                for match in re.findall(r"<testsuite[\s\S]*?</testsuite>", log):
                    try:
                        suites_xml.append(ET.fromstring(match))
                    except Exception:
                        continue

            for suite in suites_xml:
                for testcase in suite.iter("testcase"):
                    classname = testcase.get("classname") or ""
                    name = testcase.get("name") or "unknown"
                    full_name = f"{classname}::{name}" if classname else name
                    status = "pass"
                    if testcase.find("failure") is not None or testcase.find("error") is not None:
                        status = "fail"
                    elif testcase.find("skipped") is not None:
                        status = "skip"
                    add_result(full_name, status)

        # Go test output
        if not results:
            for match in re.finditer(r"^---\s+(PASS|FAIL|SKIP):\s+([^\s(]+)", log, re.MULTILINE):
                status = match.group(1).lower()
                status = "pass" if status == "pass" else "skip" if status == "skip" else "fail"
                add_result(match.group(2), status)

        # Pytest-style output
        if not results:
            for match in re.finditer(r"^(\S+::\S+)\s+(PASSED|FAILED|SKIPPED|ERROR)", log, re.MULTILINE):
                state = match.group(2)
                status = "pass" if state == "PASSED" else "skip" if state == "SKIPPED" else "fail"
                add_result(match.group(1), status)

    return results
